import{_ as t,c as o,a2 as i,o as s}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"线程与进程","description":"","frontmatter":{"title":"线程与进程","category":"浏览器","excerpt":"工厂比喻：浏览器是一座工厂，进程是工厂中的车间，线程是车间内的流水线（实际运作的最小单位）。 定义：一个正在运行的程序实例，是操作系统分配资源（内存、I/O 等）的基本单位。 特性： 拥有独立的内存空间和系统资源（如文件描述符）。 可包含一..."},"headers":[],"relativePath":"articles/browser/01-basic.md","filePath":"articles/browser/01-basic.md","lastUpdated":1773591891000}'),r={name:"articles/browser/01-basic.md"};function e(a,l,c,n,d,g){return s(),o("div",null,l[0]||(l[0]=[i('<h1 id="线程与进程" tabindex="-1">线程与进程 <a class="header-anchor" href="#线程与进程" aria-label="Permalink to &quot;线程与进程&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p><strong>工厂比喻</strong>：浏览器是一座工厂，进程是工厂中的车间，线程是车间内的流水线（实际运作的最小单位）。</p></div><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">进程</p><ul><li><strong>定义</strong>：一个正在运行的程序实例，是操作系统分配资源（内存、I/O 等）的基本单位。</li><li><strong>特性</strong>： <ul><li>拥有独立的内存空间和系统资源（如文件描述符）。</li><li>可包含一个或多个线程。</li></ul></li></ul></div><div class="tip custom-block"><p class="custom-block-title">线程</p><ul><li><strong>定义</strong>：进程内的执行单元，是操作系统调度的最小单位。</li><li><strong>特性</strong>： <ul><li>同一进程的线程共享进程资源（如内存地址空间）。</li><li>每个线程拥有独立的执行流，支持并发执行。</li></ul></li></ul></div><h2 id="并行与并发" tabindex="-1">并行与并发 <a class="header-anchor" href="#并行与并发" aria-label="Permalink to &quot;并行与并发&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li><strong>并发</strong>：多个任务在同一时间段内交替执行（看似同时，实为快速切换）。</li><li><strong>并行</strong>：多个任务在同一时刻真正同时执行（需多核 CPU 支持）。</li></ul></div><h2 id="进程通信-ipc" tabindex="-1">进程通信（IPC） <a class="header-anchor" href="#进程通信-ipc" aria-label="Permalink to &quot;进程通信（IPC）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">IPC 机制</p><ul><li><strong>管道（Pipe）</strong>：半双工通信，分匿名管道（父子进程）和命名管道（任意进程）。</li><li><strong>消息队列（Message Queue）</strong>：异步通信，进程通过发送/接收消息交互。</li><li><strong>共享内存（Shared Memory）</strong>：多个进程直接读写同一内存区域（需同步机制如信号量）。</li><li><strong>信号量（Semaphore）</strong>：控制共享资源访问，解决进程同步问题。</li><li><strong>套接字（Socket）</strong>：支持跨主机或同主机进程通信（如网络请求）。</li><li><strong>信号（Signal）</strong>：软件中断，通知进程特定事件（如 <code>SIGKILL</code>）。</li></ul></div><h2 id="浏览器的进程模型" tabindex="-1">浏览器的进程模型 <a class="header-anchor" href="#浏览器的进程模型" aria-label="Permalink to &quot;浏览器的进程模型&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">多进程架构</p><ul><li><strong>浏览器进程 (Browser Process)</strong>：主控进程，管理界面、用户输入、子进程协调。</li><li><strong>渲染进程 (Renderer Process)</strong>：每个 Tab 页独立进程，负责 HTML/CSS/JS 解析渲染（沙盒隔离）。</li><li><strong>网络进程 (Network Process)</strong>：统一处理网络请求、DNS 解析、SSL/TLS 加密。</li><li><strong>GPU 进程 (GPU Process)</strong>：加速页面渲染、图形处理（如 CSS 3D 变换）。</li></ul></div><h2 id="浏览器的线程模型" tabindex="-1">浏览器的线程模型 <a class="header-anchor" href="#浏览器的线程模型" aria-label="Permalink to &quot;浏览器的线程模型&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">渲染进程内的 5 类线程</p><ol><li><strong>GUI 渲染线程</strong>：解析 HTML/CSS、构建 DOM/CSSOM、绘制页面（与 JS 引擎互斥）。</li><li><strong>JS 引擎线程</strong>：执行 JavaScript 代码（如 V8 引擎，单线程运行）。</li><li><strong>事件触发线程</strong>：管理事件队列（点击、键盘事件），通知 JS 引擎处理回调。</li><li><strong>定时器线程</strong>：处理 <code>setTimeout</code>/<code>setInterval</code> 计时，到期后通知事件线程。</li><li><strong>异步 HTTP 线程</strong>：执行 <code>XMLHttpRequest</code>/<code>Fetch</code> 请求，完成后通知事件线程。</li></ol></div><h2 id="网络进程详解" tabindex="-1">网络进程详解 <a class="header-anchor" href="#网络进程详解" aria-label="Permalink to &quot;网络进程详解&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">核心职责</p><ol><li>管理网络请求（HTTP/WebSocket）和响应。</li><li>执行 DNS 解析、建立 TCP 连接。</li><li>处理 SSL/TLS 加密、证书验证。</li><li>管理 HTTP 缓存策略（强缓存/协商缓存）。</li></ol></div><div class="tip custom-block"><p class="custom-block-title">内部线程分工</p><ul><li><strong>DNS 解析线程</strong>：专责域名 → IP 的转换。</li><li><strong>SSL 线程</strong>：处理加密握手、证书校验。</li><li><strong>网络 I/O 线程</strong>：收发网络数据包（TCP/UDP 层）。</li><li><strong>IPC 线程</strong>：与其他进程（如渲染进程）通信。</li></ul></div><h2 id="事件循环机制" tabindex="-1">事件循环机制 <a class="header-anchor" href="#事件循环机制" aria-label="Permalink to &quot;事件循环机制&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">核心概念</p><ul><li><strong>单线程模型</strong>：JS 引擎线程同一时间只能执行一个任务。</li><li><strong>运行机制</strong>： <ol><li>同步任务在主线程直接执行。</li><li>异步任务（网络请求、定时器）交由对应线程处理。</li><li>异步任务完成后，回调函数推入<strong>任务队列</strong>。</li><li>主线程空闲时，按优先级轮询队列（微任务 → 宏任务）。</li></ol></li><li><strong>队列类型</strong>： <ul><li><strong>微任务队列</strong>：<code>Promise.then</code>、<code>MutationObserver</code>（优先执行）。</li><li><strong>宏任务队列</strong>：<code>setTimeout</code>、<code>setInterval</code>、DOM 事件。</li></ul></li></ul></div>',18)]))}const h=t(r,[["render",e]]);export{p as __pageData,h as default};
